import {projectNavigation} from './oncall-navigation.js';
import {escapeHtml as esc} from './message-format.js';
import {resultValue} from './oncall-planning.js';
const key=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');
const time=n=>n?new Date(Number(n/1000000n)).toLocaleString([], {dateStyle:'medium',timeStyle:'short'}):'Not yet';
const stamp=x=>JSON.stringify(x,(_,v)=>typeof v==='bigint'?String(v):v);
export function sourceStatus(s,now=Date.now()) {return s.revokedAt?'Revoked':Number(s.expiresAt/1000000n)<=now?'Key expired':s.enabled?'Enabled':s.testedAt?'Paused':'Awaiting connection test';}
export function connectionCommands(endpoint){
 const test=`read -r -s DESK_ALERT_KEY\n# Paste the key, then press Enter. Keep it in your server's secret store.\ncurl --fail-with-body -X POST '${endpoint}/test' \\\n  -H "Authorization: Bearer $DESK_ALERT_KEY" \\\n  -H 'Content-Type: application/json' --data '{}'`;
 const event=`# Use one new occurrence ID per outage, retained through all retries.\n# Persist sequence and occurredAt in your integration; do not regenerate on retry.\nOCCURRED_AT="$(($(date +%s) * 1000))"\ncurl --fail-with-body -X POST '${endpoint}/events' \\\n  -H "Authorization: Bearer $DESK_ALERT_KEY" \\\n  -H 'Content-Type: application/json' --data @- <<JSON\n{\n  "alertId": "healthcheck-outage-001",\n  "sequence": "1",\n  "occurredAt": "$OCCURRED_AT",\n  "state": "firing",\n  "title": "API health check failed",\n  "detail": "Synthetic integration exercise. Verify before closing.",\n  "severity": "major"\n}\nJSON`;
 return{test,event};
}
export function createOncallAlerts({root,api,session,getMe,endpoint}){
 let generation=0,identity='',timer,dirty=false,secretVisible=false;
 const token=()=>session.load(),who=()=>JSON.stringify([getMe()?.id,getMe()?.role]);
 function clear(){generation++;clearTimeout(timer);root.oninput=null;dirty=false;secretVisible=false;root.querySelector('[data-source-secret]')?.remove();}
 function active(g){if(g!==generation)return false;if(identity!==who()||getMe()?.role!=='admin'){clear();root.replaceChildren();return false;}return true;}
 const notice=text=>{const el=root.querySelector('[data-source-status]');if(el)el.textContent=text;};
 const status='<p data-source-status role="status" aria-live="polite"></p>';
 async function run(button,work,done){const g=generation;if(!active(g)||button.disabled)return;button.disabled=true;notice('Saving…');try{const result=await work();if(result.err){throw Error(typeof result.err==='string'?result.err:resultValue(result));}if(active(g))await done(result.ok);}catch(e){if(active(g))notice(e.message.replace('This plan changed','This source changed'));}finally{if(active(g)&&button.isConnected)button.disabled=false;}}
 async function show(w,mode='sources'){
  clear();identity=who();const g=generation;
  if(getMe()?.role!=='admin'){root.innerHTML='<h2>Source setup requires an administrator</h2><p>Manage Desk roles in Hub.</p>';return;}
  if(!active(g))return;
  const [sources]=await api().oncallAlertSources(token(),w.project.id);if(!active(g))return;
  if(!sources){root.innerHTML='<h2>Sources unavailable</h2><p>Check your administrator access in Hub.</p>';return;}
  const base=`#/oncall/${w.project.id}`,id=mode.startsWith('source-')&&mode!=='source-new'?BigInt(mode.slice(7)):null,s=sources.find(x=>x.id===id);
  root.innerHTML=`<a class="back-link" href="${base}">← ${esc(w.project.name)}</a><div class="page-heading"><div><span class="eyebrow">ALERT SOURCES</span><h2>${mode==='sources'?'Alert sources':mode==='source-new'?'Connect a monitoring source.':esc(s?.name||'Source unavailable')}</h2><p class="lead">${mode==='sources'?'One source, one service. Repeated alerts become one incident.':mode==='source-new'?'Choose where its alerts belong. The key can only send monitoring events.':s?esc(s.service)+' · '+sourceStatus(s):'This source may have been removed.'}</p></div>${mode==='sources'?`<a class="button primary" href="${base}/source-new">Connect a source ＋</a>`:`<a class="button" href="${base}/sources">All sources</a>`}</div>${projectNavigation(w,'sources','<button class="sm" data-source-refresh>Refresh</button>')}${status}`;
  if(mode==='source-new'){editor(w,base,sources);return;}
  if(mode==='sources'){
   root.insertAdjacentHTML('beforeend',`<div class="oc-source-steps"><span><b>1</b> Connect a source</span><span><b>2</b> Test without paging</span><span><b>3</b> Enable incident creation</span></div><div class="oc-incident-list">${sources.map(x=>`<a class="card oc-incident-row" href="${base}/source-${x.id}"><div><span class="eyebrow">${esc(x.service)}</span><h3>${esc(x.name)}</h3><p>Last accepted event · ${time(x.receivedAt)}</p>${x.lastError?`<p class="oc-response-alert">${esc(x.lastError)}</p>`:''}</div><div><strong>${sourceStatus(x)}</strong><span class="rowsub">Key expires ${time(x.expiresAt)}</span></div></a>`).join('')||'<section class="card oc-empty"><h3>Bring your monitoring into Desk.</h3><p>Connect a server-side webhook adapter using the documented event format. No monitoring vendor or phone service is required.</p></section>'}</div><p class="oc-footnote">Recovery updates the monitoring signal. A responder still verifies and closes the incident.</p>`);
  }else if(s){detail(w,s,base);}
  root.oninput=()=>{dirty=true;};
  root.querySelector('[data-source-refresh]').onclick=()=>{if(dirty||secretVisible){notice('Finish or cancel your edit and store the displayed key before refreshing.');return;}show(w,mode).catch(e=>notice(e.message));};
  poll(w,mode,sources);
 }
 function poll(w,mode,old){const g=generation;timer=setTimeout(async()=>{if(!active(g))return;try{const[fresh]=await api().oncallAlertSources(token(),w.project.id);if(!active(g))return;if(!fresh){clear();root.innerHTML='<h2>Sources unavailable</h2><p>Your Hub access changed.</p>';return;}if(stamp(fresh)!==stamp(old)){if(dirty||secretVisible||root.contains(document.activeElement)&&document.activeElement?.matches('input,select,textarea,button'))notice('Source updated. Finish your current step, then refresh.');else{await show(w,mode);return;}}poll(w,mode,old);}catch(e){if(active(g)){notice('Connection check failed. Refresh before relying on this status.');poll(w,mode,old);}}},10000);}
 function reveal(secret){
  if(!secret){notice('Source already created. Its key cannot be retrieved; rotate it to get a new key.');return;}
  secretVisible=true;const box=document.createElement('section');box.className='card oc-source-key';box.dataset.sourceSecret='';
  box.innerHTML='<span class="eyebrow">COPY ONCE</span><h3>Store this key in your integration.</h3><p>It only sends alerts to this source. Desk stores its digest; the key will disappear when you leave this page.</p><label for="sourceSecret">Source API key</label><input id="sourceSecret" type="text" readonly autocomplete="off" spellcheck="false"><div class="btnrow"><button data-copy-key>Copy key</button><button data-hide-key>I have stored the key</button></div>';
  box.querySelector('input').value=secret;root.querySelector('.oc-module-nav').after(box);
  box.querySelector('[data-copy-key]').onclick=()=>copy(box.querySelector('input').value);
  box.querySelector('[data-hide-key]').onclick=()=>{box.querySelector('input').value='';box.remove();secretVisible=false;notice('Key hidden. Use the connection test below, then refresh.');};
 }
 async function copy(text){try{await navigator.clipboard.writeText(text);notice('Copied.');}catch(_){notice('Clipboard unavailable. Select the text and copy it manually.');}}
 function editor(w,base,sources){const requestKey=key();root.querySelector('[data-source-refresh]').remove();
  root.insertAdjacentHTML('beforeend',`<form class="card oc-form"><label for="sName">Source name</label><input id="sName" required maxlength="60" placeholder="e.g. Production health checks"><label for="sService">Affected service</label><select id="sService">${w.project.services.map(x=>`<option>${esc(x)}</option>`).join('')}</select><label for="sDays">Key expires after · days</label><input id="sDays" type="number" min="1" max="365" value="90" required><p class="kv">The source starts paused. Verify the connection before enabling real incidents. Permissions remain managed in Hub.</p><div class="btnrow"><button class="primary" type="submit">Create source & key</button><a class="button" href="${base}/sources">Cancel</a></div></form>`);
  root.querySelector('form').onsubmit=e=>{e.preventDefault();run(e.submitter,()=>api().createOncallAlertSource(token(),requestKey,{projectId:w.project.id,name:root.querySelector('#sName').value.trim(),service:root.querySelector('#sService').value,days:BigInt(root.querySelector('#sDays').value)}),async r=>{window.history.replaceState(null,'',base+'/source-'+r.id);const pending=show(w,'source-'+r.id),g=generation;await pending;if(active(g))reveal(r.secret);});};
  // Check authority while the form is open without discarding its input.
  root.oninput=()=>{dirty=true;};poll(w,'source-new',sources);
 }
 function detail(w,s,base){const revoked=!!s.revokedAt,expired=Number(s.expiresAt/1000000n)<=Date.now(),path=`${endpoint}/oncall/v1/sources/${s.id}`,commands=connectionCommands(path);
  root.insertAdjacentHTML('beforeend',`<section class="card oc-source-control"><div><span class="eyebrow">${sourceStatus(s).toUpperCase()}</span><h3>${revoked?'This source cannot receive events.':expired?'Replace the expired key.':!s.testedAt?'Verify the connection first.':s.enabled?'Ready for monitoring events.':'Ready when you are.'}</h3><p>${s.enabled&&!revoked&&!expired?'New outages start response automatically. Duplicates keep the same incident.':revoked?'Existing incidents remain available under their retention policy.':!s.testedAt?'Run the connection test below. It sends no notification.':'Enable to create incidents from new firing events.'}</p></div>${!revoked?`<button class="${s.enabled?'':'primary'}" data-source-action="${s.enabled?'pause':'enable'}" ${!s.enabled&&(!s.testedAt||expired)?'disabled':''}>${s.enabled?'Pause intake':'Enable source'}</button>`:''}</section><div class="oc-source-facts"><div><span>Connection tested</span><strong>${time(s.testedAt)}</strong></div><div><span>Last accepted event</span><strong>${time(s.receivedAt)}</strong></div><div><span>Accepted / rejected requests</span><strong>${s.accepted} / ${s.rejected}</strong></div></div>${s.lastError?`<p class="warnbox">${esc(s.lastError)}</p>`:''}<p class="kv">No events can also mean a quiet service. This timestamp is not a monitoring heartbeat.</p>${!revoked?`<section class="card oc-source-guide"><span class="eyebrow">CONNECTION GUIDE</span><h3>Test. Enable. Send an event.</h3><p>Use this server-side endpoint. Browser widgets and customer-support keys cannot use it.</p><label for="sEndpoint">Event endpoint</label><input readonly id="sEndpoint" value="${esc(path+'/events')}"><h4>1 · Verify your key without creating an incident</h4><p>Run in Bash or Zsh on your integration host. Paste the key at the hidden prompt.</p><pre data-code="test"></pre><button class="sm" data-copy="test">Copy connection test</button><p class="kv">Expect HTTP 200, then refresh this page and enable the source.</p><details><summary>2 · Send a firing event — starts real response</summary><p>After enabling, run this controlled exercise. It creates an incident and starts Hub notifications. Use a new alertId for each separate outage.</p><pre data-code="event"></pre><button class="sm" data-copy="event">Copy event example</button><p>For recovery, keep the alertId, increase sequence to "2", use the recovery timestamp and set state to "recovered". Keep every field, including title, detail and severity.</p></details><details><summary>Event fields & retry rules</summary><div class="table-scroll"><table><tbody>${[['alertId','One unique, non-personal ID per outage occurrence; reuse only for that occurrence. 1–128 ASCII letters/numbers or . - _ :'],['sequence','Positive increasing integer, sent as a string. Persist it; exact retries keep the original event.'],['occurredAt','Unix milliseconds as a string. Up to 24 hours old or 5 minutes ahead; must not move backwards.'],['state','firing or recovered. Recovery never acknowledges, resolves or cancels response.'],['title / detail','Title 3–160 characters; detail up to 2000. Avoid credentials and personal data.'],['severity','minor, major or critical. All currently use the project’s response timing.']].map(([a,b])=>`<tr><th>${a}</th><td>${b}</td></tr>`).join('')}</tbody></table></div><p>All seven fields are required strings. Extra or duplicate fields are rejected. An older sequence is ignored. A reused sequence with changed content returns 409. Recovery arriving first prevents a delayed firing message from creating an incident. A resolved occurrence never reopens; a new outage needs a new ID.</p><p>2xx means accepted by Desk, not delivered to a person. Retry network failures, 429 and 503 with the same event and backoff; for 429 wait at least 60 seconds. Correct 400/401/403/409/415 errors before retrying. Paused sources return 409. Do not regenerate timestamps on retries.</p></details><details><summary>Key management & operating limits</summary><p>Key expires ${time(s.expiresAt)}. ${s.previousUntil?`The previous key remains accepted until ${time(s.previousUntil)}.`:''} Rotation gives the previous key up to 15 minutes to finish switching. For a suspected leak, revoke this source and create a replacement.</p><div class="btnrow"><button data-rotate>Rotate key</button><button data-revoke>Revoke source…</button></div><div data-key-action></div><p class="kv">60 authenticated requests/minute/source, 600/minute/Desk; 8 KB bodies; 2,000 occurrence markers/source and 20,000/Desk. Markers contain digests, counters and timestamps, retained for 731 days to outlive incident retention. Event bodies live only in the incident. Auth failures are not added to source history. Hub downtime can delay notifications while intake continues; check delivery evidence in the incident. Generic webhook contract; vendor adapters, including Watch, are not bundled yet.</p></details></section>`:''}`);
  root.querySelectorAll('[data-code]').forEach(e=>e.textContent=commands[e.dataset.code]);
  root.querySelectorAll('[data-copy]').forEach(e=>e.onclick=()=>copy(commands[e.dataset.copy]));
  const reload=()=>show(w,'source-'+s.id);
  root.querySelector('[data-source-action]')?.addEventListener('click',e=>run(e.currentTarget,()=>api().setOncallAlertSource(token(),s.id,s.revision,{[e.currentTarget.dataset.sourceAction]:null}),reload));
  root.querySelector('[data-rotate]')?.addEventListener('click',()=>{dirty=true;const box=root.querySelector('[data-key-action]');box.innerHTML='<form><label for="sRotateDays">New key expires after · days</label><input type="number" id="sRotateDays" min="1" max="365" required value="90"><div class="btnrow"><button type="submit">Create replacement key</button><button type="button" data-cancel>Cancel</button></div></form>';box.querySelector('[data-cancel]').onclick=()=>{box.replaceChildren();dirty=false;};box.querySelector('form').onsubmit=e=>{e.preventDefault();run(e.submitter,()=>api().rotateOncallAlertKey(token(),s.id,s.revision,BigInt(box.querySelector('input').value)),async r=>{const pending=reload(),g=generation;await pending;if(active(g))reveal(r.secret);});};});
  root.querySelector('[data-revoke]')?.addEventListener('click',()=>{dirty=true;const box=root.querySelector('[data-key-action]');box.innerHTML='<p>This permanently rejects both keys. It does not close existing incidents.</p><div class="btnrow"><button data-confirm>Revoke this source</button><button data-cancel>Cancel</button></div>';box.querySelector('[data-cancel]').onclick=()=>{box.replaceChildren();dirty=false;};box.querySelector('[data-confirm]').onclick=e=>run(e.currentTarget,()=>api().setOncallAlertSource(token(),s.id,s.revision,{revoke:null}),reload);});
 }
 return{show,clear};
}
